    """Test that 10 digits are formatted as (XXX) XXX-XXXX per spec."""
    result = format_phone("1234567890")
    # Per docstring: format should be (XXX) XXX-XXXX
    assert result == "(123) 456-7890", f"Expected '(123) 456-7890', got '{result}'"


def test_format_phone_various_numbers():
