    """Test that spaces raise ValueError per spec."""
    try:
        format_phone("123 456 7890")
        assert False, "Should have raised ValueError"
    except ValueError:
        pass


def test_format_phone_rejects_country_code():
    """Test that country codes raise ValueError per spec."""
    try:
        format_phone("11234567890")
        assert False, "Should have raised ValueError"
    except ValueError:
        pass


