    try:
        format_phone("123456789a")
        assert False, "Should have raised ValueError"
    except ValueError:
        pass


def test_format_phone_empty_string():
    """Test that empty string raises ValueError."""
    try:
        format_phone("")
        assert False, "Should have raised ValueError"
    except ValueError:
        pass

